export interface TransportMetrics {
  /** Whether external transport is currently enabled (gauge) */
  transportEnabled: boolean;
  /** Current transport mode label */
  transportMode: TransportMode;
  /** Total transport failures */
  failuresTotal: number;
  /** Total transport successes */
  successesTotal: number;
  /** Latency samples (last 100) for summary calculation */
  latencySamples: number[];
  /** Average latency in ms */
  latencyAvgMs: number;
  /** P50 latency in ms */
  latencyP50Ms: number;
  /** P95 latency in ms */
  latencyP95Ms: number;
  /** P99 latency in ms */
  latencyP99Ms: number;
  /** Transport selection count by mode */
  selectionCountByMode: Record<TransportMode, number>;
  /** Last transport switch timestamp */
  lastTransportSwitchAt: number | null;
  /** Transport switch count */
  transportSwitchCount: number;
}

// ============================================================================
// CONFIGURATION
// ============================================================================

export interface TransportSelectorConfig {
  /** HTTP API URL for Gravito */
  httpApiUrl: string | null;
--- external health ---
export interface GravitoExternalHealthMetrics {
  /** Whether the external Gravito is reachable */
  reachable: boolean;
  /** Circuit breaker state */
  circuitBreakerState: 'closed' | 'open' | 'half_open';
  /** Total calls attempted */
  totalCalls: number;
  /** Successful calls */
  successfulCalls: number;
  /** Failed calls */
  failedCalls: number;
  /** Fallback rate (0-1) */
